      "replacement": "<link href=\"/pagefind/pagefind-ui.css\" rel=\"stylesheet\">\n<script src=\"/pagefind/pagefind-ui.js\"></script>",
      "reason": "Executable example URLs were changed from root-relative to parent-relative, changing resolution and potentially breaking Pagefind. The locale image-path rule does not apply to these code URLs."
    },
    {
